import assert from 'node:assert/strict';
for (let mask=0;mask<256;mask++) {
 let h0=0,h1=0,expected=0;const positions=[];
 for(let i=0;i<8;i++) if(mask&(1<<i)) {if(i<4)h0|=0x80<<(8*i);else h1|=0x80<<(8*(i-4));expected|=0x80000000>>>i;positions.push(i);}
 const packed=Math.imul((h0>>>3)|(h1>>>7),0x08040201)&0xff000000;
 assert.equal(packed,expected);
 let bits=packed,previous=-1;const decoded=[];
 while(bits!==0) {const step=Math.clz32(bits)+1;previous+=step;bits<<=step;decoded.push(previous);}
 assert.deepEqual(decoded,positions);
}
console.log(JSON.stringify({runtime:process.version,packPatterns:256,relativeDecodePatterns:256}));

