import assert from 'node:assert/strict';
import { readFileSync,writeFileSync,existsSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { pathToFileURL } from 'node:url';
import { resolve } from 'node:path';
import { createHash } from 'node:crypto';
import { PerformanceObserver } from 'node:perf_hooks';
import { analyzeBlocks } from '../../../test/benchmark/helpers/abba.ts';
const tails=n=>Array.from({length:8},(_,i)=>n+i);
const cases=[
 {name:'256/control',sizes:tails(256),width:32,unicode:false},
 {name:'2KiB/lines32/all-tails',sizes:tails(2048),width:32,unicode:false},
 {name:'16KiB/lines32/all-tails',sizes:tails(16384),width:32,unicode:false},
 {name:'1MiB/lines32/all-tails',sizes:tails(1048576),width:32,unicode:false},
 {name:'1MiB/unicode/all-tails',sizes:tails(1048576),width:32,unicode:true},
 {name:'1MiB/long-lines/all-tails',sizes:tails(1048576),width:4096,unicode:false},
 {name:'1MiB/dense/all-tails',sizes:tails(1048576),width:1,unicode:false},
 {name:'16KiB/LF/all-tails',sizes:tails(16384),width:32,unicode:false,ending:'\n'},
 {name:'16KiB/CR/all-tails',sizes:tails(16384),width:32,unicode:false,ending:'\r'},
 {name:'16KiB/CRLF/all-tails',sizes:tails(16384),width:32,unicode:false,ending:'\r\n'},
 {name:'1MiB/no-endings/all-tails',sizes:tails(1048576),width:1048584,unicode:false},
].reverse();
function source(n,width,unicode,ending){const chars=unicode?'中文é😀\u010a\u010d':'abcdefghijklmnop';const row=chars.repeat(Math.ceil(width/chars.length)).slice(0,width);const pattern=ending===undefined?row+'\n'+row+'\r\n'+row+'\r':row+ending;return pattern.repeat(Math.ceil(n/pattern.length)).slice(0,n);}
function expected(s){let count=0,last=0;for(let i=0;i<s.length;i++){if(s.charCodeAt(i)===13){if(s.charCodeAt(i+1)===10)i++;count++;last=i+1;}else if(s.charCodeAt(i)===10){count++;last=i+1;}}return count+(last<s.length?1:0);}
const args=process.argv.slice(2);
if(args[0]==='--worker'){
 const {BlockLines}=await import(pathToFileURL(resolve(args[1])).href);const out={};let sink=0;
 for(const c of cases){
  const sources=c.sizes.map(n=>source(n,c.width,c.unicode,c.ending)),lines=new BlockLines();
  for(const s of sources){lines.scan(s);assert.equal(lines.length,expected(s));assert.equal(lines.next(lines.length-1),s.length);}
  const run=()=>{for(const s of sources){lines.scan(s);sink^=lines.length+lines.next(lines.length-1);}};
  const events=[];const observer=new PerformanceObserver(list=>events.push(...list.getEntries().map(e=>({startTime:e.startTime,duration:e.duration,kind:e.detail?.kind}))));observer.observe({entryTypes:['gc']});
  const drain=()=>new Promise(done=>setImmediate(done));
  globalThis.gc();let t=performance.now();while(performance.now()-t<100)run();globalThis.gc();await drain();
  t=performance.now();while(performance.now()-t<50)run();await drain();
  const memoryBefore=process.memoryUsage(),cpuStart=process.cpuUsage(),start=performance.now();let count=0;
  while(performance.now()-start<200){run();count++;}
  const end=performance.now(),cpu=process.cpuUsage(cpuStart),memoryAfter=process.memoryUsage();await drain();await drain();observer.disconnect();
  const gc=events.filter(e=>e.startTime>=start&&e.startTime<end);
  out[c.name]={ns:(end-start)*1e6/count,count,elapsedMs:end-start,cpu,memoryBefore,memoryAfter,gcCount:gc.length,gcMs:gc.reduce((n,e)=>n+e.duration,0)};
 }
 console.log(JSON.stringify({out,sink}));
}else{
 const [a,b,output]=args;assert.ok(!existsSync(output));const files=[a,b,import.meta.filename];const hashes=()=>Object.fromEntries(files.map(p=>[p,createHash('sha256').update(readFileSync(p)).digest('hex')]));
 const report={status:'incomplete',runtime:process.version,inputs:hashes(),cases,method:'Four ABBA/BAAB blocks, fresh process per observation; Reversed predeclared case order. Reused line table in both variants. Each case GC,100ms warmup,GC,50ms settle,200ms natural-GC timing. One operation scans all sizes listed, preserving alternation. Process external/arrayBuffer memory are snapshots, not peak memory or total allocation.',results:{}};
 for(let block=0;block<4;block++)for(const variant of (block%2?'BAAB':'ABBA')){
  process.stderr.write(`scan ${block+1}/4 ${variant}\n`);
  const r=spawnSync(process.execPath,['--expose-gc',import.meta.filename,'--worker',variant==='A'?a:b],{encoding:'utf8',timeout:30000,maxBuffer:8*1024*1024});assert.equal(r.status,0,r.stderr);
  for(const [name,sample] of Object.entries(JSON.parse(r.stdout).out)){(report.results[name]??={runs:[]}).runs.push({variant,...sample});}
  writeFileSync(output,JSON.stringify(report,null,2));
 }
 for(const r of Object.values(report.results))r.summary=analyzeBlocks(r.runs);
 assert.deepEqual(hashes(),report.inputs);report.status='complete';writeFileSync(output,JSON.stringify(report,null,2));
 console.log(JSON.stringify(Object.fromEntries(Object.entries(report.results).map(([n,r])=>[n,r.summary])),null,2));
}

