import assert from 'node:assert/strict';
const positions=new Uint32Array(256);
for(let mask=1;mask<256;mask++){const rest=mask&(mask-1);positions[mask]=(positions[rest]<<3)|(~Math.clz32(mask^rest)&7);}
for(let mask=1;mask<256;mask++) {
 const expected=[];for(let i=0;i<8;i++)if(mask&(1<<i))expected.push(i);
 let events=positions[mask];const actual=[];do{actual.push(events&7);}while((events>>>=3)!==0);
 assert.deepEqual(actual,expected);
}
for(let mask=0;mask<65536;mask++){
 const hits=[0,0,0,0];for(let i=0;i<16;i++)if(mask&(1<<i))hits[i>>>2]|=0x80<<((i&3)*8);
 const packed=(Math.imul((hits[0]>>>4)|hits[1],0x00204081)>>>24)|((Math.imul((hits[2]>>>4)|hits[3],0x00204081)>>>16)&0xff00);
 assert.equal(packed,mask);
}
console.log(JSON.stringify({runtime:process.version,sentinelFreePositionPatterns:255,sixteenLaneMasks:65536}));

