import assert from 'node:assert/strict';
import {writeFileSync} from 'node:fs';
const detect=word=>{const x=word^(word&0x01010101)*7^0x0a0a0a0a;return (x-0x01010101&~x&0x80808080)>>>0;};
const pack=mask=>Math.imul(mask,0x00204081)>>>28;
let checks=0;
function check(word){let expected=0,packed=0;for(let i=0;i<4;i++){const b=word>>>(i*8)&255;if(b===10||b===13){expected|=0x80<<(i*8);packed|=1<<i;}}assert.equal(detect(word),expected>>>0);assert.equal(pack(detect(word)),packed);checks++;}
for(let x=0;x<65536;x++)for(let lane=0;lane<3;lane++)check((0xeeeeeeee&~(65535<<(lane*8)))|x<<(lane*8));
for(let x=0;x<256;x++)check(Math.imul(x,0x01010101));
let state=0x46837;for(let i=0;i<500000;i++){state^=state<<13;state^=state>>>17;state^=state<<5;check(state);}
for(let m=0;m<16;m++){let mask=0;for(let i=0;i<4;i++)if(m&1<<i)mask|=0x80<<(i*8);assert.equal(pack(mask),m);}
const summary={wordChecks:checks,packPatterns:16};
for(const name of process.argv.length > 2 ? process.argv.slice(2) : ['baseline','ctz8','table8','stream8','padded']){
 const {BlockLines}=await import(new URL(name+'-export.mjs',import.meta.url));let count=0;
 const rows=l=>Array.from({length:l.length},(_,i)=>[l.start(i),l.end(i),l.next(i)]);
 function oracle(s){const out=[];for(let i=0;i<s.length;){let end=i;while(end<s.length&&s[end]!=='\r'&&s[end]!=='\n')end++;let next=end<s.length?end+1:end;if(s[end]==='\r'&&s[next]==='\n')next++;out.push([i,end,next]);i=next;}return out;}
 const lines=new BlockLines();
 const all=String.fromCharCode(...Array.from({length:65536},(_,i)=>i));
 for(let align=0;align<16;align++)for(const text of [all,[...all].reverse().join('')]){
  const source='x'.repeat(align)+text;lines.scan(source);assert.deepEqual(rows(lines),oracle(source));assert.equal(lines.normalizeLineEndings(source),source.replace(/\r\n|\r/g,'\n'));count++;
 }

 for(const prefix of ['x'.repeat(2048),'x'.repeat(2047)+'\r','x'.repeat(2056),'x'.repeat(2055)+'\r']){
  for(let width=0;width<8;width++)for(let n=0;n<4**width;n++){
   let tail='',bits=n;for(let i=0;i<width;i++){tail+=['x','\r','\n','\u010a'][bits&3];bits>>>=2;}
   const source=prefix+tail;lines.scan(source);assert.deepEqual(rows(lines),oracle(source));assert.equal(lines.normalizeLineEndings(source),source.replace(/\r\n|\r/g,'\n'));count++;
  }
 }
 // Exact constructor capacities and saturated line endings exercise final-block reservations.
 for(let rem=0;rem<16;rem++)for(const ending of ['\n','\r','\r\n']){
  const source=ending.repeat(2056).slice(0,2048+rem);const expected=oracle(source);const exact=new BlockLines(source.length,expected.length);exact.scan(source);assert.deepEqual(rows(exact),expected);if(ending.length===1)assert.equal(exact.start(expected.length),undefined);count++;
 }
 summary[name]={tailAndCapacityChecks:count};
 console.log(name,count);
}
writeFileSync(new URL('proof-wide16.json',import.meta.url),JSON.stringify(summary,null,2));console.log(summary);
